import { AggregateRoot, DomainError, notImplemented } from '@agentic-ddd/core';
import { AgentEntity, AgentMethod, Invariant } from '@agentic-ddd/decorators';
import { TaskCreated, TaskCompleted } from './task.events';

@AgentEntity({ description: 'Tarefa com título e ciclo de vida pendente ou concluído.', states: ['pending', 'completed'] })
@Invariant({ id: 'titulo-obrigatorio', text: 'Toda tarefa precisa de título não vazio.' })
export class Task extends AggregateRoot<string> {
  #status: 'pending' | 'completed' = 'pending';
  private constructor(id: string, readonly title: string) { super(id); }
  get status(): 'pending' | 'completed' { return this.#status; }

  @AgentMethod({ description: 'Cria uma tarefa pendente e remove espaços nas extremidades do título.', emits: [TaskCreated] })
  static create(id: string, title: string): Task {
    const normalized = title.trim();
    if (normalized === '') throw new DomainError('TASK_TITLE_REQUIRED', 'Toda tarefa precisa de título não vazio.');
    const task = new Task(id, normalized);
    task.record(new TaskCreated({ taskId: id, title: normalized }));
    return task;









  }

  @AgentMethod({ description: 'Conclui uma tarefa pendente; repetição falha com TASK_ALREADY_COMPLETED.', transition: { from: ['pending'], to: 'completed' }, emits: [TaskCompleted] })
  complete(): void {
    return notImplemented();













  }
}

import { describe, expect, test } from 'bun:test';
import { DomainError } from '@agentic-ddd/core';
import { covers } from '@agentic-ddd/testing';
import { Task } from '../domain/task';
import { TaskCreated } from '../domain/task.events';

describe('Task', () => {
  test(covers(['invariant:Task/titulo-obrigatorio'], 'rejeita título vazio ou só com espaços'), () => {
    for (const title of ['', '   ', '\t\n']) {
      let caught: unknown;
      try {
        Task.create('t1', title);
      } catch (error) {
        caught = error;
      }
      expect(caught).toBeInstanceOf(DomainError);
      expect((caught as DomainError).code).toBe('TASK_TITLE_REQUIRED');
    }
  });

  test(covers(['method:Task.create'], 'cria tarefa pendente com título normalizado e registra TaskCreated'), () => {
    const task = Task.create('t1', '  Comprar leite  ');
    expect(task.id).toBe('t1');
    expect(task.title).toBe('Comprar leite');
    expect(task.status).toBe('pending');

    const events = task.pullEvents();
    expect(events).toHaveLength(1);
    expect(events[0]).toBeInstanceOf(TaskCreated);
    expect(events[0]!.payload).toEqual({ taskId: 't1', title: 'Comprar leite' });
  });

  test(covers(['invariant:Task/titulo-obrigatorio', 'method:Task.create'], 'criação com título válido não lança e não registra evento vazio'), () => {
    const task = Task.create('t2', 'Estudar');
    expect(task.title).toBe('Estudar');
    expect(task.pullEvents()).toHaveLength(1);
    expect(task.pullEvents()).toHaveLength(0);
  });

  test(covers(['method:Task.create', 'criterion:0001/criacao'], 'id t1 e título com espaços nas extremidades'), () => {
    const task = Task.create('t1', '   Ler livro   ');
    expect(task.status).toBe('pending');
    expect(task.title).toBe('Ler livro');
    const events = task.pullEvents();
    expect(events[0]).toBeInstanceOf(TaskCreated);
    expect(events[0]!.payload).toEqual({ taskId: 't1', title: 'Ler livro' });
  });

  test(covers(['invariant:Task/titulo-obrigatorio', 'criterion:0001/titulo-invalido'], 'título vazio ou só com espaços rejeita com TASK_TITLE_REQUIRED'), () => {
    expect(() => Task.create('t1', '')).toThrow(DomainError);
    expect(() => Task.create('t1', '    ')).toThrow(DomainError);
    try {
      Task.create('t1', '   ');
      throw new Error('esperava DomainError');
    } catch (error) {
      expect((error as DomainError).code).toBe('TASK_TITLE_REQUIRED');
    }
  });
});
